solution.solution.rs:
use std::alloc::{alloc, dealloc, handle_alloc_error, Layout};
use std::ptr::NonNull;

struct RawStack {
    ptr: NonNull<i32>,
    len: usize,
    capacity: usize,
}

impl RawStack {
    fn new(capacity: usize) -> RawStack {
        if capacity == 0 {
            return RawStack { ptr: NonNull::dangling(), len: 0, capacity: 0 };
        }
        let layout = Layout::array::<i32>(capacity).expect("capacity too large");
        // SAFETY: the layout has a non-zero size because capacity > 0.
        let raw = unsafe { alloc(layout) } as *mut i32;
        let ptr = NonNull::new(raw).unwrap_or_else(|| handle_alloc_error(layout));
        RawStack { ptr, len: 0, capacity }
    }

    fn push(&mut self, value: i32) -> Result<(), i32> {
        if self.len == self.capacity {
            return Err(value);
        }
        // SAFETY: len < capacity, so the slot is inside the allocation.
        unsafe { self.ptr.as_ptr().add(self.len).write(value) };
        self.len += 1;
        Ok(())
    }

    fn pop(&mut self) -> Option<i32> {
        if self.len == 0 {
            return None;
        }
        self.len -= 1;
        // SAFETY: the slot at the old len - 1 was written by push and is inside the allocation.
        Some(unsafe { self.ptr.as_ptr().add(self.len).read() })
    }

    fn peek(&self) -> Option<i32> {
        self.as_slice().last().copied()
    }

    fn len(&self) -> usize {
        self.len
    }

    fn is_empty(&self) -> bool {
        self.len == 0
    }

    fn as_slice(&self) -> &[i32] {
        // SAFETY: the first len slots are initialised; the pointer is aligned and non-null (dangling is fine for len 0).
        unsafe { std::slice::from_raw_parts(self.ptr.as_ptr(), self.len) }
    }
}

impl Drop for RawStack {
    fn drop(&mut self) {
        if self.capacity > 0 {
            let layout = Layout::array::<i32>(self.capacity).unwrap();
            // SAFETY: the memory was allocated in new with this exact layout and is freed once.
            unsafe { dealloc(self.ptr.as_ptr() as *mut u8, layout) };
        }
    }
}

unitTests:
test("push and pop", || {
    let mut s = RawStack::new(3);
    check(s.is_empty());
    check_eq(s.push(1), Ok(()));
    check_eq(s.push(2), Ok(()));
    check_eq(s.push(3), Ok(()));
    check_eq(s.push(4), Err(4));
    check_eq(s.as_slice(), &[1, 2, 3][..]);
    check_eq(s.peek(), Some(3));
    check_eq(s.pop(), Some(3));
    check_eq(s.pop(), Some(2));
    check_eq(s.len(), 1);
    check_eq(s.push(9), Ok(()));
    check_eq(s.as_slice(), &[1, 9][..]);
});

test("capacity zero", || {
    let mut s = RawStack::new(0);
    check_eq(s.push(1), Err(1));
    check_eq(s.pop(), None);
    check_eq(s.as_slice().len(), 0);
});

test("many stacks come and go", || {
    for round in 0..1000 {
        let mut s = RawStack::new(64);
        for i in 0..64 { s.push(i * round).unwrap(); }
        check_eq(s.as_slice().iter().sum::<i32>(), (0..64).sum::<i32>() * round);
    }
});

